pub fn lookup(name: []const u8) ?[5]@import("../limits.zig").Usage {
    for (records) |rec| if (std.mem.eql(u8, name, rec.name)) return rec.usage;
    return null;
}

test "main 13.0 receipts: unique registered launches and all measured usages fit" {
    const t = std.testing;
    for (records, 0..) |rec, i| {
        for (records[0..i]) |previous| try t.expect(!std.mem.eql(u8, rec.name, previous.name));
        var named: ?r.CudaRecord = null;
        for (r.all_cuda) |entry| if (std.mem.eql(u8, entry.launch.name, rec.name)) {
            named = entry;
            break;
        };
        var entry = named orelse return error.UnregisteredReceipt;
        try t.expectEqualDeep(rec.usage, r.usageFor(entry, .{ .major = 13, .minor = 0 }));
        entry.usage = rec.usage;
        try t.expectEqual(@as(usize, 0), try r.checkCuda(t.allocator, &.{entry}, true));
    }
    try t.expect(lookup("not a registered launch") == null);
}
